export function readManagedHostRunOutput(args: {
  root: string;
  runId: string;
  afterSequence?: number;
}): ManagedHostRunOutputResult {
  const paths = pathsFor(args.root, args.runId);
  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  const terminalBeforeRead = readTerminal(paths);
  if (terminalBeforeRead) assertSealedManagedHostRunArtifacts(paths, terminalBeforeRead);
  const after = Math.max(0, Math.floor(args.afterSequence ?? 0));
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  const retained = existsSync(paths.output)
    ? readBoundedUtf8(paths.output, MANAGED_HOST_RUN_OUTPUT_RETENTION_MAX_BYTES)
    : { text: '', truncated: false };
  const completeText = retained.truncated && !retained.text.endsWith('\n')
    ? retained.text.slice(0, Math.max(0, retained.text.lastIndexOf('\n') + 1))
    : retained.text;
  const allFrames = completeText
      .split('\n')
      .filter(Boolean)
      .flatMap(line => {
        try { return [JSON.parse(line) as ManagedHostRunOutputFrame]; } catch { return []; }
      })
      .filter(frame => frame.sequence > after)
    ;
  const frames = allFrames.slice(0, MANAGED_HOST_RUN_OUTPUT_READ_MAX_FRAMES);
  const hasMore = allFrames.length > frames.length;
  const nextSequence = frames.length > 0
    ? frames[frames.length - 1]!.sequence
    : snapshot.outputTruncated
      ? Math.max(after, snapshot.outputSequence)
      : after;
  const terminalAfterRead = readTerminal(paths);
  if (terminalAfterRead) assertSealedManagedHostRunArtifacts(paths, terminalAfterRead);
  return {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId: args.runId,
    frames,
    nextSequence,
    hasMore,
    truncated: (snapshot.outputTruncated ?? false) || retained.truncated,
  };
}

